-- TPC-DS Test_Query Query 100
-- Based on: query13.tpl (medium)
-- Variation: 10

select avg(ss_quantity) ,avg(ss_ext_sales_price) ,avg(ss_ext_wholesale_cost) ,sum(ss_ext_wholesale_cost) from store_sales ,store ,customer_demographics ,household_demographics ,customer_address ,date_dim where s_store_sk = ss_store_sk and  ss_sold_date_sk = d_date_sk and d_year = 1966 and((ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.1' and cd_education_status = 'ES.2' and ss_sales_price between 100.1 and 150.2 and hd_dep_count = 1 )or (ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.3' and cd_education_status = 'ES.1' and ss_sales_price between 50.2 and 100.1 and hd_dep_count = 3 ) or (ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.5' and cd_education_status = 'ES.1' and ss_sales_price between 150.1 and 200.2 and hd_dep_count = 1 )) and((ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.2', 'STATE.1', 'STATE.2') and ss_net_profit between 98 and 208 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.3', 'STATE.7', 'STATE.4') and ss_net_profit between 145 and 299 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.6', 'STATE.6', 'STATE.8') and ss_net_profit between 48 and 250 ));
